import React, { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Settings, Users, UserPlus, Copy, Check, Shield, Trash2,
  AlertTriangle, Sparkles, Mail, Globe, Crown, Eye, User,
  Palette, Laptop, Info
} from "lucide-react";
import { useWorkspace } from "../context/WorkspaceContext";
import { useAuth } from "../context/AuthContext";
import { Avatar } from "../components/layout/Sidebar";

const ICONS = ["🏢", "🚀", "⚡", "🎯", "🛠️", "🌟", "🔥", "💡", "🎨", "📦"];
const COLORS = [
  "#6366f1", // Indigo
  "#8b5cf6", // Violet
  "#ec4899", // Pink
  "#14b8a6", // Teal
  "#f97316", // Orange
  "#eab308", // Yellow
  "#22c55e", // Green
  "#3b82f6"  // Blue
];

const ROLE_META = {
  owner:  { icon: Crown,  color: "#eab308", bg: "rgba(234,179,8,0.1)",  label: "Owner" },
  admin:  { icon: Shield, color: "#a78bfa", bg: "rgba(167,139,250,0.1)", label: "Admin" },
  member: { icon: User,   color: "#94a3b8", bg: "rgba(148,163,184,0.1)", label: "Member" },
  viewer: { icon: Eye,    color: "#0ea5e9", bg: "rgba(14,165,233,0.1)",  label: "Viewer" }
};

const TabButton = ({ label, active, onClick, icon: Icon, badge }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium
      transition-all duration-200 group relative
      ${active
        ? "bg-violet-500/10 text-violet-400 font-semibold"
        : "text-slate-400 hover:text-slate-200 hover:bg-slate-800/40"
      }`}
  >
    {active && (
      <span className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-5 rounded-r bg-violet-500" />
    )}
    <Icon size={16} className={active ? "text-violet-400" : "text-slate-500 group-hover:text-slate-300"} />
    <span className="flex-1 text-left">{label}</span>
    {badge != null && (
      <span className="px-2 py-0.5 rounded-full text-xs font-bold bg-slate-800/80 text-slate-400 border border-slate-700/50">
        {badge}
      </span>
    )}
  </button>
);

const Field = ({ label, description, children }) => (
  <div className="space-y-2">
    <div>
      <label className="block text-sm font-semibold text-white">{label}</label>
      {description && <p className="text-xs text-slate-500 mt-0.5">{description}</p>}
    </div>
    {children}
  </div>
);

const WorkspaceSettings = () => {
  const { workspaceId } = useParams();
  const navigate = useNavigate();
  const { activeWorkspace, updateWorkspace, inviteMember } = useWorkspace();
  const { user } = useAuth();

  const [activeTab, setActiveTab] = useState("general");
  const [form, setForm] = useState({
    name:        activeWorkspace?.name        || "",
    description: activeWorkspace?.description || "",
    icon:        activeWorkspace?.icon        || "🏢",
    color:       activeWorkspace?.color       || "#6366f1",
  });
  const [saving, setSaving]       = useState(false);
  const [saved, setSaved]         = useState(false);
  const [saveError, setSaveError] = useState("");

  const [inviteEmail, setInviteEmail]   = useState("");
  const [inviteRole, setInviteRole]     = useState("member");
  const [inviting, setInviting]         = useState(false);
  const [inviteResult, setInviteResult] = useState(null);
  const [copiedLink, setCopiedLink]     = useState(false);

  const userRole = activeWorkspace?.members?.find((m) => m.user?._id === user?._id)?.role;
  const canEdit  = ["owner", "admin"].includes(userRole);

  const handleSave = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;
    setSaving(true);
    setSaveError("");
    const result = await updateWorkspace(workspaceId || activeWorkspace?._id, form);
    setSaving(false);
    if (result.success) {
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    } else {
      setSaveError(result.message);
    }
  };

  const handleInvite = async (e) => {
    e.preventDefault();
    if (!inviteEmail) return;
    setInviting(true);
    setInviteResult(null);
    const result = await inviteMember(workspaceId || activeWorkspace?._id, inviteEmail, inviteRole);
    setInviting(false);
    setInviteResult(result);
    if (result.success) setInviteEmail("");
  };

  const copyLink = () => {
    if (inviteResult?.invite?.inviteLink) {
      navigator.clipboard.writeText(inviteResult.invite.inviteLink);
      setCopiedLink(true);
      setTimeout(() => setCopiedLink(false), 2000);
    }
  };

  if (!activeWorkspace) {
    return (
      <div className="absolute inset-0 flex items-center justify-center text-slate-500 bg-slate-950">
        <div className="text-center space-y-2">
          <Settings size={28} className="mx-auto text-slate-600 animate-spin" />
          <p className="text-sm font-medium">Select a workspace first.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="absolute inset-0 flex bg-slate-950 overflow-hidden">

      {/* ── Settings Navigation Sidebar ─────────────────────────── */}
      <aside className="w-64 border-r border-slate-800/50 bg-slate-950/50 flex flex-col flex-shrink-0">

        {/* Workspace Quick Identity */}
        <div className="p-5 border-b border-slate-800/40">
          <div className="relative rounded-2xl p-4 overflow-hidden border border-white/5 bg-white/[0.02] flex items-center gap-3">
            <div
              className="absolute -top-10 -right-10 w-24 h-24 rounded-full blur-2xl opacity-20 pointer-events-none"
              style={{ backgroundColor: form.color }}
            />
            <div
              className="w-11 h-11 rounded-xl flex items-center justify-center text-xl shadow-lg shadow-black/40 flex-shrink-0"
              style={{
                background: `linear-gradient(135deg, ${form.color}, ${form.color}aa)`,
              }}
            >
              {form.icon}
            </div>
            <div className="min-w-0">
              <h4 className="text-sm font-bold text-white truncate leading-snug">
                {form.name || activeWorkspace.name}
              </h4>
              <p className="text-xs text-slate-500 font-medium">Workspace settings</p>
            </div>
          </div>
        </div>

        {/* Tab Items */}
        <div className="flex-1 p-3 space-y-1 overflow-y-auto">
          <TabButton
            label="General Settings"
            active={activeTab === "general"}
            onClick={() => setActiveTab("general")}
            icon={Settings}
          />
          <TabButton
            label="Members"
            active={activeTab === "members"}
            onClick={() => setActiveTab("members")}
            icon={Users}
            badge={activeWorkspace.members?.length}
          />
          {canEdit && (
            <TabButton
              label="Invite People"
              active={activeTab === "invite"}
              onClick={() => setActiveTab("invite")}
              icon={UserPlus}
            />
          )}
        </div>

        {/* Workspace Meta info */}
        <div className="p-4 border-t border-slate-800/40 bg-white/[0.01]">
          <div className="flex gap-2">
            <Info size={14} className="text-violet-400 flex-shrink-0 mt-0.5" />
            <p className="text-[11px] text-slate-500 leading-normal">
              Need help? Settings affect all workspace members.
            </p>
          </div>
        </div>

      </aside>

      {/* ── Main Panel Content ──────────────────────────────────── */}
      <main className="flex-1 overflow-y-auto bg-slate-950/20 relative">
        <div className="max-w-4xl mx-auto px-8 py-8">

          {/* ── Tab: General Settings ─────────────────────────────── */}
          {activeTab === "general" && (
            <div className="space-y-6 animate-fade-in">
              <div>
                <h1 className="text-2xl font-black text-white">General Settings</h1>
                <p className="text-slate-500 text-sm mt-1">Configure your workspace name, icon, brand colors, and description.</p>
              </div>

              {saveError && (
                <div className="px-4 py-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm flex items-center gap-2 animate-fade-in">
                  <span className="w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                  {saveError}
                </div>
              )}

              <form onSubmit={handleSave} className="space-y-6">

                {/* Meta details card */}
                <div className="p-6 rounded-2xl border border-slate-800/60 bg-white/[0.02] space-y-5">
                  <Field label="Workspace Name" description="Give your team workspace a recognizable name.">
                    <input
                      value={form.name}
                      onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
                      disabled={!canEdit}
                      placeholder="e.g. Design Team"
                      className="input-field disabled:opacity-50 disabled:cursor-not-allowed"
                    />
                  </Field>

                  <Field label="Description" description="Describe what this workspace is used to track or build.">
                    <textarea
                      value={form.description}
                      onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
                      disabled={!canEdit}
                      rows={3}
                      className="input-field resize-none disabled:opacity-50 disabled:cursor-not-allowed"
                      placeholder="e.g. Tracking marketing assets and release boards"
                    />
                  </Field>
                </div>

                {/* Appearance branding card */}
                <div className="p-6 rounded-2xl border border-slate-800/60 bg-white/[0.02] space-y-6">
                  <h3 className="text-base font-bold text-white flex items-center gap-2">
                    <Palette size={16} className="text-violet-400" />
                    Appearance & Branding
                  </h3>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

                    {/* Icon Selection */}
                    <Field label="Workspace Icon" description="Select a representative icon.">
                      <div className="flex flex-wrap gap-2 mt-1">
                        {ICONS.map((icon) => (
                          <button
                            key={icon}
                            type="button"
                            onClick={() => canEdit && setForm((f) => ({ ...f, icon }))}
                            className={`w-10 h-10 rounded-xl text-lg flex items-center justify-center transition-all duration-150
                              ${form.icon === icon
                                ? "bg-violet-500/20 ring-2 ring-violet-500 scale-105"
                                : "bg-slate-800/50 border border-slate-700/30 hover:bg-slate-800"
                              }
                              ${!canEdit ? "opacity-40 cursor-not-allowed" : "hover:scale-105"}`}
                          >
                            {icon}
                          </button>
                        ))}
                      </div>
                    </Field>

                    {/* Color selection */}
                    <Field label="Workspace Color Theme" description="Choose a custom accent color.">
                      <div className="flex flex-wrap gap-2 mt-2">
                        {COLORS.map((color) => (
                          <button
                            key={color}
                            type="button"
                            onClick={() => canEdit && setForm((f) => ({ ...f, color }))}
                            className={`w-9 h-9 rounded-full transition-all duration-150 flex-shrink-0
                              ${!canEdit ? "opacity-40 cursor-not-allowed" : "hover:scale-110"}`}
                            style={{
                              backgroundColor: color,
                              boxShadow: form.color === color
                                ? `0 0 0 3px rgba(255,255,255,0.1), 0 0 0 5px ${color}50, 0 0 15px ${color}40`
                                : "none",
                              transform: form.color === color ? "scale(1.1)" : undefined,
                            }}
                          />
                        ))}
                      </div>
                    </Field>

                  </div>
                </div>

                {/* Save action */}
                {canEdit && (
                  <div className="flex justify-end pt-2">
                    <button
                      type="submit"
                      disabled={saving}
                      className="btn-primary px-8 py-3 shadow-lg shadow-violet-500/20"
                    >
                      {saved ? (
                        <><Check size={16} /> Saved Successfully!</>
                      ) : saving ? (
                        <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> Saving…</>
                      ) : (
                        "Save Workspace Changes"
                      )}
                    </button>
                  </div>
                )}

              </form>
            </div>
          )}

          {/* ── Tab: Members ──────────────────────────────────────── */}
          {activeTab === "members" && (
            <div className="space-y-6 animate-fade-in">
              <div className="flex items-center justify-between">
                <div>
                  <h1 className="text-2xl font-black text-white">Workspace Members</h1>
                  <p className="text-slate-500 text-sm mt-1">Manage team members, roles, and collaborative permissions.</p>
                </div>
                <span className="text-xs font-semibold px-3 py-1 rounded-full border border-slate-700/60 bg-slate-800/40 text-slate-300">
                  {activeWorkspace.members?.length || 0} Total members
                </span>
              </div>

              {/* Members table card */}
              <div className="rounded-2xl border border-slate-800/60 bg-white/[0.02] overflow-hidden">
                <div className="divide-y divide-slate-800/50">
                  {activeWorkspace.members?.map((member) => {
                    const isYou = member.user?._id === user?._id;
                    const meta = ROLE_META[member.role] || ROLE_META.member;
                    const RoleIcon = meta.icon;

                    return (
                      <div
                        key={member.user?._id || member.user}
                        className="flex items-center justify-between p-4 hover:bg-white/[0.01] transition-all"
                      >
                        <div className="flex items-center gap-3.5 min-w-0">
                          <Avatar user={member.user} size="md" online={isYou} />
                          <div className="min-w-0">
                            <p className="text-sm font-semibold text-white truncate flex items-center gap-2">
                              {member.user?.name || "Unknown Collaborator"}
                              {isYou && (
                                <span className="text-[10px] font-medium px-2 py-0.5 rounded bg-violet-500/10 text-violet-400 border border-violet-500/20">
                                  You
                                </span>
                              )}
                            </p>
                            <p className="text-xs text-slate-500 truncate">{member.user?.email}</p>
                          </div>
                        </div>

                        {/* Role tag */}
                        <div className="flex items-center gap-2 flex-shrink-0">
                          <span
                            className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold"
                            style={{
                              backgroundColor: meta.bg,
                              color: meta.color,
                              border: `1px solid ${meta.color}20`
                            }}
                          >
                            <RoleIcon size={11} />
                            {meta.label}
                          </span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

            </div>
          )}

          {/* ── Tab: Invite ───────────────────────────────────────── */}
          {activeTab === "invite" && canEdit && (
            <div className="space-y-6 animate-fade-in">
              <div>
                <h1 className="text-2xl font-black text-white">Invite Collaborators</h1>
                <p className="text-slate-500 text-sm mt-1">Add coworkers and colleagues to coordinate real-time board updates.</p>
              </div>

              <div className="p-6 rounded-2xl border border-slate-800/60 bg-white/[0.02] space-y-5">
                <form onSubmit={handleInvite} className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">

                    {/* Invite Email */}
                    <div className="md:col-span-2 space-y-2">
                      <label className="block text-sm font-semibold text-white">Email Address</label>
                      <div className="relative">
                        <Mail size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-500" />
                        <input
                          type="email"
                          value={inviteEmail}
                          onChange={(e) => setInviteEmail(e.target.value)}
                          placeholder="name@company.com"
                          className="input-field pl-10"
                        />
                      </div>
                    </div>

                    {/* Role Selection */}
                    <div className="space-y-2">
                      <label className="block text-sm font-semibold text-white">Workspace Role</label>
                      <select
                        value={inviteRole}
                        onChange={(e) => setInviteRole(e.target.value)}
                        className="input-field select-field"
                      >
                        <option value="member">Member (Read/Write)</option>
                        <option value="admin">Admin (All settings)</option>
                        <option value="viewer">Viewer (Read-only)</option>
                      </select>
                    </div>

                  </div>

                  <div className="flex justify-end pt-2">
                    <button
                      type="submit"
                      disabled={inviting || !inviteEmail}
                      className="btn-primary px-8 py-3"
                    >
                      <UserPlus size={16} />
                      {inviting ? "Sending Invitation…" : "Send Invite Link"}
                    </button>
                  </div>
                </form>

                {inviteResult && (
                  <div className={`p-4 rounded-xl border text-sm animate-fade-in
                    ${inviteResult.success
                      ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-400"
                      : "bg-red-500/10 border-red-500/20 text-red-400"}`}
                  >
                    {inviteResult.success ? (
                      <div className="space-y-3">
                        <p className="font-semibold flex items-center gap-2">
                          <Check size={16} /> Invitation link generated successfully!
                        </p>
                        <div className="flex items-center gap-2 bg-slate-900/80 px-3 py-2 rounded-xl border border-slate-800">
                          <code className="flex-1 text-xs text-slate-300 truncate">
                            {inviteResult.invite?.inviteLink}
                          </code>
                          <button
                            onClick={copyLink}
                            type="button"
                            className={`p-2 rounded-lg transition-all
                              ${copiedLink
                                ? "text-emerald-400 bg-emerald-500/10 border border-emerald-500/25"
                                : "text-slate-400 hover:text-white hover:bg-slate-800"
                              }`}
                          >
                            {copiedLink ? <Check size={14} /> : <Copy size={14} />}
                          </button>
                        </div>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2">
                        <span className="w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                        {inviteResult.message}
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Informative tips */}
              <div className="p-4 rounded-xl border border-slate-800 bg-white/[0.01] flex gap-3">
                <Globe size={16} className="text-violet-400 mt-0.5 flex-shrink-0" />
                <div>
                  <h4 className="text-xs font-semibold text-white">Secure Invite Sharing</h4>
                  <p className="text-[11px] text-slate-500 mt-0.5 leading-relaxed">
                    Invite links allow users to register and join automatically. They expire after 7 days.
                  </p>
                </div>
              </div>
            </div>
          )}

        </div>
      </main>

    </div>
  );
};

export default WorkspaceSettings;
